import { setTimeout as delay } from 'node:timers/promises';

// Every conversational/fortune result is generated by the deployed model. Owner-scoped
// preference/title mutations exercise the same permissions as the application UI.
export async function runCases({ id, client, admin, assert, observations, request }) {
  const same = (left, right) => JSON.stringify(left) === JSON.stringify(right);
  let hadFailure = false;
  const check = (condition, name) => { try { assert(condition, name); } catch { hadFailure = true; /* Keep independent evidence after a model-dependent assertion. */ } };
  const read = async query => {
    const result = await query;
    if (result.error) throw new Error('Test database operation failed');
    return result.data;
  };
  async function poll(fetchValue, matches, duration = 25_000) {
    const until = Date.now() + duration;
    let value;
    do {
      value = await fetchValue();
      if (matches(value)) return value;
      await delay(750);
    } while (Date.now() < until);
    return value;
  }
  async function conversation() {
    return (await read(client.from('conversations').insert({ user_id: id, character_id: 'BOMI' }).select('id').single())).id;
  }
  async function state(conv) {
    return read(client.from('conversations').select('title,title_custom,title_generated_at,summary,last_extracted_message_id,relationship_state').eq('id', conv).single());
  }
  const memories = () => read(client.from('memories').select('id,scope,character_id,subject,content,disabled_at,source_conversation_id').eq('user_id', id));
  async function waitExtracted(conv, messageId, label) {
    const result = await poll(() => state(conv), value => value.last_extracted_message_id === messageId);
    check(result.last_extracted_message_id === messageId, `${label} background extraction cursor commits`);
    return result.last_extracted_message_id === messageId;
  }
  async function chat(conv, message, label, consultationId = null) {
    const result = await request('chat', { action: 'SEND', conversationId: conv, consultationId, message });
    observations.push({ name: label, status: result.data?.executionStatus ?? 'FAILED', code: result.error?.code ?? null });
    assert(result.ok && result.data?.executionStatus === 'SUCCEEDED' && result.data.assistantMessage?.id, `${label} receives a real durable Chat response`);
    return result.data;
  }
  const profile = await read(client.from('profiles').update({ memory_enabled: true }).eq('id', id).select('memory_enabled').single());
  assert(profile.memory_enabled, 'synthetic owner explicitly enables memory');
  const conv = await conversation();
  // 1: exact harmless preference fixture; it must reach memory through actual extraction.
  const seed = await chat(conv, '나는 오래 즐겨 온 취미가 종이별 접기야. 꾸준히 만드는 종이별을 가장 좋아해. 다음에 이야기할 때도 이 취향을 기억해 줘.', 'preference seed');
  await waitExtracted(conv, seed.userMessage.id, 'preference seed');
  let stored = await memories();
  const hasPreference = stored.some(row => row.subject === 'USER' && !row.disabled_at && /종이별/.test(row.content));
  check(hasPreference, 'actual extraction stores the explicit harmless preference');
  const durable = await read(client.from('messages').select('id,sender,reply_to_message_id,model_id,prompt_version').eq('id', seed.assistantMessage.id).single());
  assert(durable.sender === 'ASSISTANT' && durable.reply_to_message_id === seed.userMessage.id && durable.model_id && durable.prompt_version, 'Chat stores model provenance and its original user-message link');

  // 2: explicit intent only recommends; no fortune execution happens until DRAW below.
  // Engineering11.1 prioritizes the named tool. Exact spread selection belongs to
  // Tarot DRAW8.1; Chat SEND7.1 does not have a requested-spread input field.
  const intent = await chat(conv, '이번 주 취미 모임에서 먼저 인사를 건네도 좋을지 타로로 보고 싶어.', 'explicit Tarot recommendation', seed.consultationId);
  const supportedTarotModes = ['ONE_CARD', 'GENERAL_3', 'RELATIONSHIP_3', 'DECISION_3', 'DAILY'];
  const validTarotRecommendation = Boolean(intent.recommendation?.recommendedTools?.some(item => item.tool === 'TAROT' && supportedTarotModes.includes(item.mode)));
  observations.push({ name: 'actual structured recommendation', tools: intent.recommendation?.recommendedTools?.map(item => ({ tool: item.tool, mode: item.mode, missingSlotCount: item.missingSlots?.length ?? 0 })) ?? null });
  check(validTarotRecommendation, 'real structured extraction returns the explicitly requested Tarot tool');
  const persistedIntent = await read(client.from('messages').select('metadata').eq('id', intent.assistantMessage.id).single());
  check(validTarotRecommendation && same(persistedIntent.metadata.recommendation, intent.recommendation), 'non-null structured recommendation survives message reload');
  assert((await read(client.from('tarot_draw_groups').select('id').eq('user_id', id))).length === 0, 'recommendation alone never draws cards');
  await waitExtracted(conv, intent.userMessage.id, 'explicit recommendation');
  const titles = await poll(async () => ({ conversation: await state(conv), consultation: await read(client.from('consultations').select('title,title_generated_at,title_custom').eq('id', seed.consultationId).single()) }), value => value.conversation.title_generated_at && value.consultation.title_generated_at);
  check(Boolean(titles.conversation.title_generated_at && titles.conversation.title && titles.conversation.title !== '새로운 이야기'), 'actual model generates a conversation title after at least three messages');
  check(Boolean(titles.consultation.title_generated_at && titles.consultation.title), 'actual model generates the consultation title');
  const manualTitle = '내가 정한 종이공예 이야기';
  await read(client.from('conversations').update({ title: manualTitle }).eq('id', conv));
  await read(client.from('consultations').update({ title: manualTitle }).eq('id', seed.consultationId));

  // 3: explicit new UUID generates a new answer while preserving the original USER row.
  const retry = await request('chat', { action: 'RETRY_RESPONSE', conversationId: conv, userMessageId: seed.userMessage.id });
  assert(retry.ok && retry.data?.executionStatus === 'SUCCEEDED', 'actual model completes Chat reinterpretation');
  assert(retry.data.userMessage.id === seed.userMessage.id && retry.data.assistantMessage.id !== seed.assistantMessage.id, 'Chat retry reuses one user-message ID and creates a new assistant message');
  const userRows = await read(client.from('messages').select('id').eq('conversation_id', conv).eq('sender', 'USER'));
  assert(userRows.length === 2, 'Chat retry creates no duplicate user message');
  const retryState = await state(conv);
  assert(retryState.relationship_state.completedTurns === 2, 'Chat retry does not inflate completed relationship turns');
  await delay(1_000);
  const protectedConversation = await state(conv), protectedConsultation = await read(client.from('consultations').select('title,title_custom').eq('id', seed.consultationId).single());
  assert(protectedConversation.title === manualTitle && protectedConversation.title_custom && protectedConsultation.title === manualTitle && protectedConsultation.title_custom, 'subsequent real replies preserve both manually edited titles');

  // 4–5: real Tarot interpretation/reload/retry, no seeded interpretation.
  const tarot = await request('tarot', { action: 'DRAW', conversationId: conv, consultationId: null, spreadType: 'ONE_CARD', question: '이번 취미 모임에서 편하게 말을 걸기 위해 내가 해 볼 행동은?', mode: 'NORMAL', clientTimezone: 'Asia/Seoul' });
  observations.push({ name: 'Tarot interpretation', status: tarot.data?.executionStatus ?? 'FAILED', code: tarot.data?.partialError?.details?.reason ?? tarot.error?.code ?? null });
  assert(tarot.ok && tarot.data?.executionStatus === 'SUCCEEDED' && tarot.data.interpretation?.messageId, 'actual model completes and persists the Tarot interpretation');
  const cards = await read(client.from('tarot_draws').select('card_id,orientation,position_index').eq('draw_group_id', tarot.data.drawGroupId).order('position_index'));
  assert(cards.length === 1 && cards[0].card_id === tarot.data.cards[0].cardId && cards[0].orientation === tarot.data.cards[0].orientation, 'Tarot reload preserves the authoritative card and orientation');
  const tarotMessage = await read(client.from('messages').select('content,metadata').eq('id', tarot.data.interpretation.messageId).single());
  assert(tarotMessage.content === tarot.data.interpretation.content && tarotMessage.metadata.tarot?.drawGroupId === tarot.data.drawGroupId, 'Tarot interpretation reload includes the same persisted draw');
  const tarotRetry = await request('tarot', { action: 'RETRY_INTERPRETATION', conversationId: conv, drawGroupId: tarot.data.drawGroupId });
  assert(tarotRetry.ok && tarotRetry.data?.executionStatus === 'SUCCEEDED' && tarotRetry.data.interpretation?.messageId !== tarot.data.interpretation.messageId, 'actual Tarot retry generates a new durable interpretation');
  assert(same(tarotRetry.data.cards, tarot.data.cards) && (await read(client.from('tarot_draw_groups').select('id').eq('user_id', id))).length === 1, 'Tarot retry preserves cards and never redraws');

  // 6: a fresh conversation cannot retrieve the original raw chat history.
  const recallConv = await conversation();
  const recall = await chat(recallConv, '내가 오래 즐겨 온 취미가 무엇이었는지 기억하고 있으면 말해 줘.', 'fresh-conversation memory recall');
  check(hasPreference && /종이별/.test(recall.assistantMessage.content), 'real reply reuses extracted memory without the original conversation history');
  await waitExtracted(recallConv, recall.userMessage.id, 'fresh recall');

  // 7: per-message opt-out must advance its cursor without storing the new preference.
  const privateConv = await conversation();
  const privateReply = await chat(privateConv, '이 이야기는 기억하지 마. 나는 은빛 모빌 만들기를 꾸준히 좋아해.', 'per-message memory opt-out');
  await waitExtracted(privateConv, privateReply.userMessage.id, 'private turn');
  check(!(await memories()).some(row => /은빛|모빌/.test(row.content)), 'explicit do-not-remember preference is absent from structured memory');

  // 8: profile opt-out excludes existing memory even in a fresh conversation.
  await read(client.from('profiles').update({ memory_enabled: false }).eq('id', id));
  const disabledProfileConv = await conversation();
  const profileOff = await chat(disabledProfileConv, '내가 오래 즐겨 온 취미가 무엇이었는지 기억하고 있으면 말해 줘.', 'profile memory disabled');
  check(!/종이별/.test(profileOff.assistantMessage.content), 'profile opt-out prevents reuse of the stored preference');
  const offState = await state(disabledProfileConv);
  assert(offState.last_extracted_message_id === null && offState.summary === null, 'profile opt-out leaves no extraction cursor or summary in the new conversation');
  await read(client.from('profiles').update({ memory_enabled: true }).eq('id', id));

  // 9: disabling actual extracted rows creates a content-free suppression key.
  stored = await memories();
  const ownIds = stored.filter(row => row.subject === 'USER').map(row => row.id);
  if (ownIds.length) await read(client.from('memories').update({ disabled_at: new Date().toISOString() }).in('id', ownIds));
  const disabledConv = await conversation();
  const disabled = await chat(disabledConv, '내가 오래 즐겨 온 취미가 무엇이었는지 기억하고 있으면 말해 줘.', 'individual memory disabled');
  check(hasPreference && !/종이별/.test(disabled.assistantMessage.content), 'disabled memory is excluded from a real fresh-conversation reply');
  await waitExtracted(disabledConv, disabled.userMessage.id, 'disabled memory recall');
  const suppression = await read(admin.from('memory_suppressions').select('scope,character_key,subject').eq('user_id', id).eq('subject', 'USER'));
  check(ownIds.length > 0 && suppression.length > 0 && suppression.every(row => Object.keys(row).every(key => ['scope', 'character_key', 'subject'].includes(key))), 'disabling an actual memory creates a content-free USER suppression');

  // 10: deleting those rows does not let a new extraction resurrect the preference.
  await read(client.from('memories').delete().eq('user_id', id).eq('subject', 'USER'));
  const deletedConv = await conversation();
  const deleted = await chat(deletedConv, '나는 종이별 접기를 오랫동안 좋아해. 꾸준히 만드는 종이별이 가장 마음에 들어.', 'deleted-memory repeated preference');
  await waitExtracted(deletedConv, deleted.userMessage.id, 'deleted-memory repeat');
  check(hasPreference && !(await memories()).some(row => row.subject === 'USER'), 'deleted USER memory is not re-extracted after a fresh repeated statement');

  // 11–12: separate related-person opt-in, actual extraction, then consent withdrawal.
  const person = await read(client.from('related_people').insert({ user_id: id, display_name: '솔새', relation: '친구', memory_opt_in: true }).select('id,memory_opt_in,birth_data_opt_in').single());
  assert(person.memory_opt_in && !person.birth_data_opt_in, 'related-person memory consent is separate from birth-data storage consent');
  const relatedConv = await conversation();
  const related = await chat(relatedConv, '내 친구 솔새는 바람개비 만들기를 오래 즐겨 왔어. 솔새의 꾸준한 취미는 바람개비 만들기야.', 'related-person opt-in');
  await waitExtracted(relatedConv, related.userMessage.id, 'related opt-in');
  const subject = `RELATED_PERSON:${person.id}`;
  const relatedStored = (await memories()).filter(row => row.subject === subject);
  check(relatedStored.some(row => /바람개비/.test(row.content)), 'actual model extracts the opted-in related-person preference under its authorized subject');
  await read(client.from('related_people').update({ memory_opt_in: false }).eq('id', person.id));
  assert(!(await memories()).some(row => row.subject === subject), 'related-person consent withdrawal immediately deletes their memory');
  const revokedConv = await conversation();
  const revoked = await chat(revokedConv, '내 친구 솔새는 바람개비 만들기를 오래 즐겨 왔어. 솔새의 꾸준한 취미는 바람개비 만들기야.', 'related-person consent withdrawn');
  await waitExtracted(revokedConv, revoked.userMessage.id, 'related consent withdrawn');
  assert(!(await memories()).some(row => row.subject === subject), 'subsequent actual extraction cannot recreate a non-consenting related-person memory');
  assert((await read(client.from('birth_profiles').select('id').eq('user_id', id))).length === 0, 'conversation memory tests never create a birth profile');
  observations.push({ name: 'usage', measuredNeurons: null, reason: 'Edge envelopes do not expose provider usage; run capped at 12 live operations within the reserved allowance.' });
  observations.push({ name: 'summary compaction', tested: false, reason: 'More than 16 user turns or 14,400 context characters are required; excluded from this bounded live run.' });
  observations.push({ name: 'idempotency note', sameUuidReplay: false, reason: 'This run tests explicit new-UUID interpretation retry; prior remote smoke covers network replay.' });
  if (hadFailure) throw new Error('One or more model-dependent conversation assertions failed');
}
